FILES['clients/templates/clients/dog_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Psy{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-suit-heart-fill" style="color: #D4AF37;"></i> Psy</h1>\n    <div>\n        <a href="{% url \'dog_archived_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-archive"></i> Archiwum\n        </a>\n        <a href="{% url \'dog_create\' %}" class="btn btn-primary">\n            <i class="bi bi-plus-lg"></i> Dodaj psa\n        </a>\n    </div>\n</div>\n\n<div class="search-bar">\n    <form method="get" class="row g-2 align-items-center">\n        <div class="col-md-10">\n            <div class="input-group">\n                <span class="input-group-text bg-white border-0"><i class="bi bi-search"></i></span>\n                <input type="text" name="q" class="form-control border-0" placeholder="Szukaj po imieniu psa, rasie lub wlascicielu..." value="{{ search_query }}">\n            </div>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-primary w-100"><i class="bi bi-funnel"></i> Szukaj</button>\n        </div>\n    </form>\n    {% if search_query %}\n        <div class="mt-2">\n            <a href="{% url \'dog_list\' %}" class="btn btn-sm btn-outline-secondary">\n                <i class="bi bi-x-circle"></i> Wyczysc\n            </a>\n        </div>\n    {% endif %}\n</div>\n\n<div class="row">\n    {% for dog in page_obj %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            {% if dog.photo %}\n                <img src="{{ dog.photo.url }}" class="card-img-top" alt="{{ dog.name }}">\n            {% else %}\n                <div class="card-img-placeholder"><i class="bi bi-image"></i></div>\n            {% endif %}\n            <div class="card-body">\n                <h5 class="card-title">{{ dog.name }}</h5>\n                {% if dog.breed %}<p class="text-muted small mb-1">{{ dog.breed }}</p>{% endif %}\n                {% if dog.get_age_display %}<p class="text-muted small mb-1"><i class="bi bi-cake2"></i> {{ dog.get_age_display }}</p>{% endif %}\n                <p class="small mb-0"><i class="bi bi-person"></i> <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a></p>\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <a href="{% url \'dog_detail\' dog.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-eye"></i> Szczegoly\n                </a>\n                <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-sm btn-outline-secondary">\n                    <i class="bi bi-pencil"></i>\n                </a>\n                <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-sm btn-outline-danger">\n                    <i class="bi bi-archive"></i>\n                </a>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p class="mb-3">\n                {% if search_query %}\n                    Nie znaleziono psow spelniajacych kryteria.\n                {% else %}\n                    Brak psow w bazie.\n                {% endif %}\n            </p>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n\n{% if page_obj.paginator.num_pages > 1 %}\n<nav class="d-flex justify-content-center mt-4">\n    <ul class="pagination">\n        {% if page_obj.has_previous %}\n            <li class="page-item"><a class="page-link" href="?page=1">&laquo;&laquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.previous_page_number }}">&laquo;</a></li>\n        {% endif %}\n        <li class="page-item disabled"><span class="page-link">Strona {{ page_obj.number }} z {{ page_obj.paginator.num_pages }}</span></li>\n        {% if page_obj.has_next %}\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.next_page_number }}">&raquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.paginator.num_pages }}">&raquo;&raquo;</a></li>\n        {% endif %}\n    </ul>\n</nav>\n{% endif %}\n{% endblock %}\n'
FILES['clients/templates/clients/dog_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n{% if fixed_owner %}\n<p class="text-muted">Wlasciciel: <strong>{{ fixed_owner.full_name }}</strong></p>\n{% endif %}\n\n<div class="form-card">\n    <form method="post" enctype="multipart/form-data">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        {% if not fixed_owner %}\n        <div class="mb-3">\n            <label class="form-label">Wlasciciel</label>\n            {{ form.owner }}\n            {% if form.owner.errors %}<div class="invalid-feedback-custom">{{ form.owner.errors|first }}</div>{% endif %}\n        </div>\n        {% else %}\n            {{ form.owner }}\n        {% endif %}\n\n        <div class="mb-3">\n            <label class="form-label">Imie psa</label>\n            {{ form.name }}\n            {% if form.name.errors %}<div class="invalid-feedback-custom">{{ form.name.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Rasa (opcjonalnie)</label>\n            {{ form.breed }}\n        </div>\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Data urodzenia (opcjonalnie)</label>\n                {{ form.birth_date }}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Waga w kg (opcjonalnie)</label>\n                {{ form.weight_kg }}\n            </div>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Informacje zdrowotne / przeciwwskazania</label>\n            {{ form.health_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Notatki trenera</label>\n            {{ form.trainer_notes }}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label"><i class="bi bi-image"></i> Zdjecie (opcjonalnie)</label>\n            {{ form.photo }}\n            {% if form.photo.errors %}<div class="invalid-feedback-custom">{{ form.photo.errors|first }}</div>{% endif %}\n            {% if dog and dog.photo %}\n                <div class="mt-2">\n                    <img src="{{ dog.photo.url }}" style="max-width:150px;border-radius:10px;" alt="{{ dog.name }}">\n                </div>\n            {% endif %}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            {% if fixed_owner %}\n                <a href="{% url \'owner_detail\' fixed_owner.pk %}" class="btn btn-secondary">Anuluj</a>\n            {% else %}\n                <a href="{% url \'dog_list\' %}" class="btn btn-secondary">Anuluj</a>\n            {% endif %}\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ dog.name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}</h1>\n    <div>\n        <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'dog_delete\' dog.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_detail\' dog.owner.pk %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot do wlasciciela\n        </a>\n    </div>\n</div>\n\n<div class="row">\n    <div class="col-md-4">\n        {% if dog.photo %}\n            <img src="{{ dog.photo.url }}" class="img-fluid rounded mb-3" alt="{{ dog.name }}">\n        {% else %}\n            <div class="card-img-placeholder mb-3" style="height:250px;"><i class="bi bi-image"></i></div>\n        {% endif %}\n    </div>\n    <div class="col-md-8">\n        <div class="detail-section">\n            <p><i class="bi bi-person"></i> Wlasciciel: <a href="{% url \'owner_detail\' dog.owner.pk %}">{{ dog.owner.full_name }}</a></p>\n            {% if dog.breed %}<p><i class="bi bi-tag"></i> Rasa: {{ dog.breed }}</p>{% endif %}\n            {% if dog.get_age_display %}<p><i class="bi bi-cake2"></i> Wiek: {{ dog.get_age_display }}</p>{% endif %}\n            {% if dog.weight_kg %}<p><i class="bi bi-speedometer2"></i> Waga: {{ dog.weight_kg }} kg</p>{% endif %}\n\n            {% if dog.health_notes %}\n                <div class="alert alert-warning mt-3">\n                    <i class="bi bi-exclamation-triangle-fill"></i>\n                    <strong>Informacje zdrowotne:</strong> {{ dog.health_notes|linebreaks }}\n                </div>\n            {% endif %}\n\n            {% if dog.trainer_notes %}\n                <hr>\n                <h6>Notatki trenera</h6>\n                <p>{{ dog.trainer_notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_confirm_delete.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwizuj psa{% endblock %}\n\n{% block content %}\n<div class="form-card">\n    <h1 class="mb-4"><i class="bi bi-archive text-warning"></i> Przenies do archiwum</h1>\n    <p>Czy na pewno chcesz przeniesc psa <strong>{{ dog.name }}</strong> do archiwum?</p>\n    <p class="text-muted">Pies nie zostanie usuniety na zawsze - znajdziesz go w sekcji "Archiwum" i bedziesz mogl go przywrocic.</p>\n\n    <form method="post">\n        {% csrf_token %}\n        <button type="submit" class="btn btn-danger"><i class="bi bi-archive"></i> Tak, przenies do archiwum</button>\n        <a href="{% url \'owner_detail\' dog.owner.pk %}" class="btn btn-secondary">Anuluj</a>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/dog_archived_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwum psow{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-archive"></i> Archiwum psow</h1>\n    <a href="{% url \'dog_list\' %}" class="btn btn-secondary">\n        <i class="bi bi-arrow-left"></i> Powrot do listy\n    </a>\n</div>\n\n<div class="form-card">\n    <table class="table">\n        <thead>\n            <tr>\n                <th>Imie psa</th>\n                <th>Wlasciciel</th>\n                <th>Zarchiwizowano</th>\n                <th>Akcje</th>\n            </tr>\n        </thead>\n        <tbody>\n            {% for dog in dogs %}\n            <tr>\n                <td>{{ dog.name }}</td>\n                <td>{{ dog.owner.full_name }}</td>\n                <td>{{ dog.updated_at|date:"d.m.Y H:i" }}</td>\n                <td>\n                    <form method="post" action="{% url \'dog_restore\' dog.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-secondary">\n                            <i class="bi bi-arrow-counterclockwise"></i> Przywroc\n                        </button>\n                    </form>\n                    <form method="post" action="{% url \'dog_delete_permanent\' dog.pk %}" style="display:inline;" onsubmit="return confirm(\'Czy na pewno chcesz usunac tego psa NA ZAWSZE? Tej operacji nie mozna odwrocic.\');">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-danger">\n                            <i class="bi bi-trash"></i> Usun na zawsze\n                        </button>\n                    </form>\n                </td>\n            </tr>\n            {% empty %}\n            <tr><td colspan="4" class="text-center text-muted">Archiwum jest puste.</td></tr>\n            {% endfor %}\n        </tbody>\n    </table>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/owner_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Klienci{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-3">\n    <h1><i class="bi bi-people" style="color: #D4AF37;"></i> Klienci</h1>\n    <div>\n        <a href="{% url \'owner_archived_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-archive"></i> Archiwum\n        </a>\n        <a href="{% url \'dog_list\' %}" class="btn btn-outline-secondary me-2">\n            <i class="bi bi-list-ul"></i> Wszystkie psy\n        </a>\n        <a href="{% url \'owner_create\' %}" class="btn btn-primary">\n            <i class="bi bi-plus-lg"></i> Dodaj klienta\n        </a>\n    </div>\n</div>\n\n<div class="stats-panel mb-4">\n    <div class="stat-box">\n        <span class="stat-number">{{ stats.owners_count }}</span>\n        <span class="stat-label">Aktywnych wlascicieli</span>\n    </div>\n    <div class="stat-box">\n        <span class="stat-number">{{ stats.dogs_count }}</span>\n        <span class="stat-label">Aktywnych psow</span>\n    </div>\n</div>\n\n<div class="search-bar">\n    <form method="get" class="row g-2 align-items-center">\n        <div class="col-md-10">\n            <div class="input-group">\n                <span class="input-group-text bg-white border-0"><i class="bi bi-search"></i></span>\n                <input type="text" name="q" class="form-control border-0" placeholder="Szukaj po imieniu, nazwisku, telefonie, emailu lub imieniu psa..." value="{{ search_query }}">\n            </div>\n        </div>\n        <div class="col-md-2">\n            <button type="submit" class="btn btn-primary w-100"><i class="bi bi-funnel"></i> Szukaj</button>\n        </div>\n    </form>\n    {% if search_query %}\n        <div class="mt-2">\n            <a href="{% url \'owner_list\' %}" class="btn btn-sm btn-outline-secondary">\n                <i class="bi bi-x-circle"></i> Wyczysc\n            </a>\n        </div>\n    {% endif %}\n</div>\n\n<div class="row">\n    {% for owner in page_obj %}\n    <div class="col-md-4 mb-4">\n        <div class="card exercise-card">\n            <div class="card-body">\n                <h5 class="card-title"><i class="bi bi-person-circle"></i> {{ owner.full_name }}</h5>\n                <p class="card-text text-muted small mb-1"><i class="bi bi-telephone"></i> {{ owner.phone }}</p>\n                {% if owner.email %}\n                <p class="card-text text-muted small mb-1"><i class="bi bi-envelope"></i> {{ owner.email }}</p>\n                {% endif %}\n                <div class="mb-2">\n                    {% for dog in owner.dogs.all %}\n                        {% if dog.is_active %}\n                        <span class="badge badge-muscle"><i class="bi bi-suit-heart-fill"></i> {{ dog.name }}</span>\n                        {% endif %}\n                    {% endfor %}\n                </div>\n            </div>\n            <div class="card-footer bg-white border-0 pb-3">\n                <a href="{% url \'owner_detail\' owner.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-eye"></i> Szczegoly\n                </a>\n                <a href="{% url \'owner_update\' owner.pk %}" class="btn btn-sm btn-outline-secondary">\n                    <i class="bi bi-pencil"></i>\n                </a>\n                <a href="{% url \'owner_delete\' owner.pk %}" class="btn btn-sm btn-outline-danger">\n                    <i class="bi bi-archive"></i>\n                </a>\n            </div>\n        </div>\n    </div>\n    {% empty %}\n    <div class="col-12">\n        <div class="empty-state">\n            <i class="bi bi-inbox"></i>\n            <p class="mb-3">\n                {% if search_query %}\n                    Nie znaleziono klientow spelniajacych kryteria.\n                {% else %}\n                    Brak klientow w bazie. Dodaj pierwszego!\n                {% endif %}\n            </p>\n            <a href="{% url \'owner_create\' %}" class="btn btn-primary">\n                <i class="bi bi-plus-lg"></i> Dodaj klienta\n            </a>\n        </div>\n    </div>\n    {% endfor %}\n</div>\n\n{% if page_obj.paginator.num_pages > 1 %}\n<nav class="d-flex justify-content-center mt-4">\n    <ul class="pagination">\n        {% if page_obj.has_previous %}\n            <li class="page-item"><a class="page-link" href="?page=1">&laquo;&laquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.previous_page_number }}">&laquo;</a></li>\n        {% endif %}\n        <li class="page-item disabled"><span class="page-link">Strona {{ page_obj.number }} z {{ page_obj.paginator.num_pages }}</span></li>\n        {% if page_obj.has_next %}\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.next_page_number }}">&raquo;</a></li>\n            <li class="page-item"><a class="page-link" href="?page={{ page_obj.paginator.num_pages }}">&raquo;&raquo;</a></li>\n        {% endif %}\n    </ul>\n</nav>\n{% endif %}\n{% endblock %}\n'
FILES['clients/templates/clients/owner_form.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ title }}{% endblock %}\n\n{% block content %}\n<h1 class="mb-4">{{ title }}</h1>\n\n<div class="form-card">\n    <form method="post">\n        {% csrf_token %}\n        {% if form.non_field_errors %}\n            <div class="alert alert-danger">{{ form.non_field_errors }}</div>\n        {% endif %}\n\n        <div class="row">\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Imie</label>\n                {{ form.first_name }}\n                {% if form.first_name.errors %}<div class="invalid-feedback-custom">{{ form.first_name.errors|first }}</div>{% endif %}\n            </div>\n            <div class="col-md-6 mb-3">\n                <label class="form-label">Nazwisko</label>\n                {{ form.last_name }}\n                {% if form.last_name.errors %}<div class="invalid-feedback-custom">{{ form.last_name.errors|first }}</div>{% endif %}\n            </div>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Telefon</label>\n            {{ form.phone }}\n            {% if form.phone.errors %}<div class="invalid-feedback-custom">{{ form.phone.errors|first }}</div>{% endif %}\n            <small class="text-muted">Format dowolny - system tylko ostrzeze, jesli numer wyglada niepoprawnie.</small>\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Email (opcjonalnie)</label>\n            {{ form.email }}\n            {% if form.email.errors %}<div class="invalid-feedback-custom">{{ form.email.errors|first }}</div>{% endif %}\n        </div>\n\n        <div class="mb-3">\n            <label class="form-label">Notatki</label>\n            {{ form.notes }}\n        </div>\n\n        <div class="mt-4">\n            <button type="submit" class="btn btn-primary"><i class="bi bi-check-lg"></i> Zapisz</button>\n            <a href="{% url \'owner_list\' %}" class="btn btn-secondary">Anuluj</a>\n        </div>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/owner_detail.html'] = '{% extends \'base.html\' %}\n{% block title %}{{ owner.full_name }}{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-person-circle"></i> {{ owner.full_name }}</h1>\n    <div>\n        <a href="{% url \'owner_update\' owner.pk %}" class="btn btn-outline-secondary">\n            <i class="bi bi-pencil"></i> Edytuj\n        </a>\n        <a href="{% url \'owner_delete\' owner.pk %}" class="btn btn-outline-danger">\n            <i class="bi bi-archive"></i> Archiwizuj\n        </a>\n        <a href="{% url \'owner_list\' %}" class="btn btn-secondary">\n            <i class="bi bi-arrow-left"></i> Powrot\n        </a>\n    </div>\n</div>\n\n<div class="row">\n    <div class="col-md-5">\n        <div class="detail-section mb-4">\n            <h5><i class="bi bi-card-text"></i> Dane kontaktowe</h5>\n            <p class="mb-1"><i class="bi bi-telephone"></i> <strong>{{ owner.phone }}</strong></p>\n            {% if owner.email %}\n                <p class="mb-1"><i class="bi bi-envelope"></i> {{ owner.email }}</p>\n            {% endif %}\n            {% if owner.notes %}\n                <hr>\n                <h6>Notatki</h6>\n                <p>{{ owner.notes|linebreaks }}</p>\n            {% endif %}\n        </div>\n    </div>\n\n    <div class="col-md-7">\n        <div class="detail-section">\n            <div class="d-flex justify-content-between align-items-center mb-3">\n                <h5 class="mb-0"><i class="bi bi-suit-heart-fill"></i> Psy ({{ dogs.count }})</h5>\n                <a href="{% url \'dog_create_for_owner\' owner.pk %}" class="btn btn-sm btn-primary">\n                    <i class="bi bi-plus-lg"></i> Dodaj psa\n                </a>\n            </div>\n            <div class="row">\n                {% for dog in dogs %}\n                <div class="col-md-6 mb-3">\n                    <div class="card exercise-card h-100">\n                        {% if dog.photo %}\n                            <img src="{{ dog.photo.url }}" class="card-img-top" style="height:150px;object-fit:cover;" alt="{{ dog.name }}">\n                        {% else %}\n                            <div class="card-img-placeholder" style="height:150px;"><i class="bi bi-image"></i></div>\n                        {% endif %}\n                        <div class="card-body">\n                            <h6 class="card-title mb-1">{{ dog.name }}</h6>\n                            {% if dog.breed %}<p class="text-muted small mb-1">{{ dog.breed }}</p>{% endif %}\n                            {% if dog.get_age_display %}<p class="text-muted small mb-0"><i class="bi bi-cake2"></i> {{ dog.get_age_display }}</p>{% endif %}\n                        </div>\n                        <div class="card-footer bg-white border-0 pb-2">\n                            <a href="{% url \'dog_detail\' dog.pk %}" class="btn btn-sm btn-primary">Szczegoly</a>\n                            <a href="{% url \'dog_update\' dog.pk %}" class="btn btn-sm btn-outline-secondary"><i class="bi bi-pencil"></i></a>\n                        </div>\n                    </div>\n                </div>\n                {% empty %}\n                <div class="col-12">\n                    <p class="text-muted">Ten klient nie ma jeszcze zadnego psa w bazie.</p>\n                </div>\n                {% endfor %}\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/owner_confirm_delete.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwizuj klienta{% endblock %}\n\n{% block content %}\n<div class="form-card">\n    <h1 class="mb-4"><i class="bi bi-archive text-warning"></i> Przenies do archiwum</h1>\n    <p>Czy na pewno chcesz przeniesc klienta <strong>{{ owner.full_name }}</strong> do archiwum?</p>\n    <p class="text-muted">Klient nie zostanie usuniety na zawsze - znajdziesz go w sekcji "Archiwum" i bedziesz mogl go przywrocic.</p>\n\n    {% if active_dogs_count > 0 %}\n        <div class="alert alert-warning">\n            <i class="bi bi-exclamation-triangle-fill"></i>\n            Ten klient ma <strong>{{ active_dogs_count }}</strong> aktywnych psow w bazie. Nie zostana one automatycznie zarchiwizowane.\n        </div>\n    {% endif %}\n\n    <form method="post">\n        {% csrf_token %}\n        <button type="submit" class="btn btn-danger"><i class="bi bi-archive"></i> Tak, przenies do archiwum</button>\n        <a href="{% url \'owner_list\' %}" class="btn btn-secondary">Anuluj</a>\n    </form>\n</div>\n{% endblock %}\n'
FILES['clients/templates/clients/owner_archived_list.html'] = '{% extends \'base.html\' %}\n{% block title %}Archiwum klientow{% endblock %}\n\n{% block content %}\n<div class="d-flex justify-content-between align-items-center mb-4">\n    <h1><i class="bi bi-archive"></i> Archiwum klientow</h1>\n    <a href="{% url \'owner_list\' %}" class="btn btn-secondary">\n        <i class="bi bi-arrow-left"></i> Powrot do listy\n    </a>\n</div>\n\n<div class="form-card">\n    <table class="table">\n        <thead>\n            <tr>\n                <th>Imie i nazwisko</th>\n                <th>Telefon</th>\n                <th>Zarchiwizowano</th>\n                <th>Akcje</th>\n            </tr>\n        </thead>\n        <tbody>\n            {% for owner in owners %}\n            <tr>\n                <td>{{ owner.full_name }}</td>\n                <td>{{ owner.phone }}</td>\n                <td>{{ owner.updated_at|date:"d.m.Y H:i" }}</td>\n                <td>\n                    <form method="post" action="{% url \'owner_restore\' owner.pk %}" style="display:inline;">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-secondary">\n                            <i class="bi bi-arrow-counterclockwise"></i> Przywroc\n                        </button>\n                    </form>\n                    <form method="post" action="{% url \'owner_delete_permanent\' owner.pk %}" style="display:inline;" onsubmit="return confirm(\'Czy na pewno chcesz usunac tego klienta NA ZAWSZE (wraz z psami)? Tej operacji nie mozna odwrocic.\');">\n                        {% csrf_token %}\n                        <button type="submit" class="btn btn-sm btn-outline-danger">\n                            <i class="bi bi-trash"></i> Usun na zawsze\n                        </button>\n                    </form>\n                </td>\n            </tr>\n            {% empty %}\n            <tr><td colspan="4" class="text-center text-muted">Archiwum jest puste.</td></tr>\n            {% endfor %}\n        </tbody>\n    </table>\n</div>\n{% endblock %}\n'
FILES['templates/base.html'] = '<!DOCTYPE html>\n<html lang="pl">\n<head>\n    <meta charset="UTF-8">\n    <meta name="viewport" content="width=device-width, initial-scale=1.0">\n    <title>{% block title %}Dog Fitness{% endblock %}</title>\n\n    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">\n    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css">\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet">\n\n    {% load static %}\n    <link rel="stylesheet" href="{% static \'css/style.css\' %}">\n</head>\n<body>\n    <nav class="navbar navbar-expand-lg navbar-custom">\n        <div class="container">\n            <a class="navbar-brand" href="{% url \'exercise_list\' %}">\n                <i class="bi bi-activity"></i> Dog Fitness\n            </a>\n            <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav">\n                <span class="navbar-toggler-icon"></span>\n            </button>\n            <div class="collapse navbar-collapse" id="navbarNav">\n                <div class="navbar-nav ms-auto align-items-lg-center">\n                    {% if user.is_authenticated %}\n                        <a class="nav-link" href="{% url \'exercise_list\' %}"><i class="bi bi-list-ul"></i> Cwiczenia</a>\n                        <a class="nav-link" href="{% url \'owner_list\' %}"><i class="bi bi-people"></i> Klienci</a>\n                        <a class="nav-link" href="{% url \'muscle_group_list\' %}"><i class="bi bi-diagram-3"></i> Grupy miesniowe</a>\n                        <a class="nav-link" href="{% url \'equipment_list\' %}"><i class="bi bi-tools"></i> Sprzet</a>\n                        <a class="nav-link" href="{% url \'storage_usage\' %}"><i class="bi bi-hdd"></i> Uzycie dysku</a>\n                        {% if user.is_staff %}\n                            <a class="nav-link" href="/admin/" target="_blank"><i class="bi bi-gear"></i> Panel admina</a>\n                        {% endif %}\n                        <span class="navbar-text-custom mx-3"><i class="bi bi-person-circle"></i> {{ user.username }}</span>\n                        <a class="nav-link" href="{% url \'logout\' %}"><i class="bi bi-box-arrow-right"></i> Wyloguj</a>\n                    {% endif %}\n                </div>\n            </div>\n        </div>\n    </nav>\n\n    <div class="container mt-4 mb-5">\n        {% if messages %}\n            {% for message in messages %}\n                <div class="alert alert-{{ message.tags|default:\'success\' }} d-flex align-items-center" role="alert">\n                    <i class="bi bi-check-circle-fill me-2"></i> {{ message }}\n                </div>\n            {% endfor %}\n        {% endif %}\n\n        {% block content %}{% endblock %}\n    </div>\n\n    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>\n    <script src="https://cdn.jsdelivr.net/npm/sortablejs@1.15.0/Sortable.min.js"></script>\n    <script>\n        function getCookie(name) {\n            let cookieValue = null;\n            if (document.cookie && document.cookie !== \'\') {\n                const cookies = document.cookie.split(\';\');\n                for (let i = 0; i < cookies.length; i++) {\n                    const cookie = cookies[i].trim();\n                    if (cookie.substring(0, name.length + 1) === (name + \'=\')) {\n                        cookieValue = decodeURIComponent(cookie.substring(name.length + 1));\n                        break;\n                    }\n                }\n            }\n            return cookieValue;\n        }\n\n        document.addEventListener(\'DOMContentLoaded\', function () {\n            document.querySelectorAll(\'.exercise-card\').forEach(function (card) {\n                const tabs = card.querySelectorAll(\'.variant-tab\');\n                tabs.forEach(function (tab) {\n                    tab.addEventListener(\'click\', function () {\n                        tabs.forEach(function (t) { t.classList.remove(\'active\'); });\n                        tab.classList.add(\'active\');\n\n                        card.querySelectorAll(\'.variant-content\').forEach(function (c) {\n                            c.style.display = \'none\';\n                        });\n                        const target = card.querySelector(\'#\' + tab.dataset.target);\n                        if (target) target.style.display = \'block\';\n\n                        const detailBtn = card.querySelector(\'.detail-link-btn\');\n                        if (detailBtn && tab.dataset.detailUrl) {\n                            detailBtn.href = tab.dataset.detailUrl;\n                        }\n                    });\n                });\n            });\n\n            document.querySelectorAll(\'.image-delete-form\').forEach(function (form) {\n                form.addEventListener(\'submit\', function (e) {\n                    if (!confirm(\'Czy na pewno chcesz usunac to zdjecie?\')) {\n                        e.preventDefault();\n                    }\n                });\n            });\n\n            const sortableEl = document.getElementById(\'existing-images-sortable\');\n            if (sortableEl && typeof Sortable !== \'undefined\') {\n                new Sortable(sortableEl, {\n                    animation: 150,\n                    ghostClass: \'sortable-ghost\',\n                    onEnd: function () {\n                        const ids = Array.from(sortableEl.children).map(function (el) {\n                            return el.dataset.id;\n                        });\n                        fetch(sortableEl.dataset.reorderUrl, {\n                            method: \'POST\',\n                            headers: {\n                                \'Content-Type\': \'application/json\',\n                                \'X-CSRFToken\': getCookie(\'csrftoken\'),\n                            },\n                            body: JSON.stringify({ order: ids })\n                        });\n                    }\n                });\n            }\n        });\n    </script>\n</body>\n</html>\n'
FILES['dogfitness/urls.py'] = "from django.contrib import admin\nfrom django.urls import path, include\nfrom django.conf import settings\nfrom django.conf.urls.static import static\nfrom django.contrib.auth import views as auth_views\n\nurlpatterns = [\n    path('admin/', admin.site.urls),\n    path('login/', auth_views.LoginView.as_view(template_name='registration/login.html'), name='login'),\n    path('logout/', auth_views.LogoutView.as_view(next_page='login'), name='logout'),\n    path('', include('exercises.urls')),\n    path('', include('clients.urls')),\n]\n\nif settings.DEBUG:\n    urlpatterns += static(settings.MEDIA_URL, document_root=settings.MEDIA_ROOT)\n"
